package main

import (
	"fmt"
	"strings"
	"time"
)

// Minimal YAML encoder/decoder for task files
// Format:
// summary: text
// notes: "" or |2-\n\n  content
// tags:\n- tag1\n- tag2
// project: text
// priority: P0-P3
// delegatedto: ""
// subtasks: []
// dependencies: []
// created: RFC3339nano
// resolved: RFC3339nano
// due: RFC3339nano

var zeroTime = time.Time{}

func encodeYAML(t Task) string {
	var sb strings.Builder

	sb.WriteString("summary: ")
	sb.WriteString(yamlString(t.Summary))
	sb.WriteString("\n")

	// notes
	if t.Notes == "" {
		sb.WriteString("notes: \"\"\n")
	} else {
		sb.WriteString("notes: |2-\n\n")
		for _, line := range strings.Split(t.Notes, "\n") {
			sb.WriteString("  ")
			sb.WriteString(line)
			sb.WriteString("\n")
		}
	}

	// tags
	if len(t.Tags) == 0 {
		sb.WriteString("tags: []\n")
	} else {
		sb.WriteString("tags:\n")
		for _, tag := range t.Tags {
			sb.WriteString("- ")
			sb.WriteString(tag)
			sb.WriteString("\n")
		}
	}

	sb.WriteString("project: ")
	sb.WriteString(yamlString(t.Project))
	sb.WriteString("\n")

	sb.WriteString("priority: ")
	sb.WriteString(string(t.Priority))
	sb.WriteString("\n")

	sb.WriteString("delegatedto: ")
	sb.WriteString(yamlString(t.DelegatedTo))
	sb.WriteString("\n")

	// subtasks
	if len(t.Subtasks) == 0 {
		sb.WriteString("subtasks: []\n")
	} else {
		sb.WriteString("subtasks:\n")
		for _, s := range t.Subtasks {
			sb.WriteString("- ")
			sb.WriteString(yamlString(s))
			sb.WriteString("\n")
		}
	}

	// dependencies
	if len(t.Dependencies) == 0 {
		sb.WriteString("dependencies: []\n")
	} else {
		sb.WriteString("dependencies:\n")
		for _, d := range t.Dependencies {
			sb.WriteString("- ")
			sb.WriteString(d)
			sb.WriteString("\n")
		}
	}

	sb.WriteString("created: ")
	sb.WriteString(t.Created.UTC().Format(time.RFC3339Nano))
	sb.WriteString("\n")

	sb.WriteString("resolved: ")
	sb.WriteString(t.Resolved.UTC().Format(time.RFC3339Nano))
	sb.WriteString("\n")

	sb.WriteString("due: ")
	sb.WriteString(t.Due.UTC().Format(time.RFC3339Nano))
	sb.WriteString("\n")

	return sb.String()
}

func yamlString(s string) string {
	if s == "" {
		return "\"\""
	}
	// If contains special chars, quote it
	if strings.ContainsAny(s, ":{}[]|>&*!,#?-") || strings.Contains(s, "  ") {
		return "\"" + strings.ReplaceAll(s, "\"", "\\\"") + "\""
	}
	return s
}

func decodeYAML(data string) (Task, error) {
	var t Task
	lines := strings.Split(data, "\n")
	i := 0

	for i < len(lines) {
		line := lines[i]
		if line == "" {
			i++
			continue
		}

		colonIdx := strings.Index(line, ": ")
		if colonIdx < 0 {
			// might be "key:" with nothing after
			if strings.HasSuffix(line, ":") {
				key := strings.TrimSpace(line[:len(line)-1])
				i++
				// read list items
				var items []string
				for i < len(lines) && strings.HasPrefix(lines[i], "- ") {
					items = append(items, strings.TrimPrefix(lines[i], "- "))
					i++
				}
				switch key {
				case "tags":
					t.Tags = items
				case "subtasks":
					t.Subtasks = items
				case "dependencies":
					t.Dependencies = items
				}
				continue
			}
			i++
			continue
		}

		key := strings.TrimSpace(line[:colonIdx])
		val := line[colonIdx+2:]

		switch key {
		case "summary":
			t.Summary = unquoteYAML(val)
		case "notes":
			if val == "\"\"" || val == "" {
				t.Notes = ""
				i++
			} else if val == "|2-" || val == "|-" || strings.HasPrefix(val, "|") {
				i++
				var notesLines []string
				// skip empty first line
				if i < len(lines) && lines[i] == "" {
					i++
				}
				for i < len(lines) {
					if lines[i] == "" {
						// could be trailing or part of notes
						if i+1 < len(lines) && (strings.HasPrefix(lines[i+1], "  ") || lines[i+1] == "") {
							notesLines = append(notesLines, "")
							i++
							continue
						}
						break
					}
					if strings.HasPrefix(lines[i], "  ") {
						notesLines = append(notesLines, strings.TrimPrefix(lines[i], "  "))
						i++
					} else {
						break
					}
				}
				// Remove trailing empty lines
				for len(notesLines) > 0 && notesLines[len(notesLines)-1] == "" {
					notesLines = notesLines[:len(notesLines)-1]
				}
				t.Notes = strings.Join(notesLines, "\n")
				continue
			} else {
				// inline string
				t.Notes = unquoteYAML(val)
				i++
			}
			continue
		case "tags":
			if val == "[]" {
				t.Tags = []string{}
				i++
			} else {
				// Should not have inline value for tags list
				i++
				var items []string
				for i < len(lines) && strings.HasPrefix(lines[i], "- ") {
					items = append(items, strings.TrimPrefix(lines[i], "- "))
					i++
				}
				t.Tags = items
				continue
			}
		case "project":
			t.Project = unquoteYAML(val)
		case "priority":
			t.Priority = Priority(val)
		case "delegatedto":
			t.DelegatedTo = unquoteYAML(val)
		case "subtasks":
			if val == "[]" {
				t.Subtasks = []string{}
				i++
			} else {
				i++
				var items []string
				for i < len(lines) && strings.HasPrefix(lines[i], "- ") {
					items = append(items, strings.TrimPrefix(lines[i], "- "))
					i++
				}
				t.Subtasks = items
				continue
			}
		case "dependencies":
			if val == "[]" {
				t.Dependencies = []string{}
				i++
			} else {
				i++
				var items []string
				for i < len(lines) && strings.HasPrefix(lines[i], "- ") {
					items = append(items, strings.TrimPrefix(lines[i], "- "))
					i++
				}
				t.Dependencies = items
				continue
			}
		case "created":
			ts, err := time.Parse(time.RFC3339Nano, val)
			if err != nil {
				ts, err = time.Parse(time.RFC3339, val)
				if err != nil {
					return t, fmt.Errorf("bad created time: %w", err)
				}
			}
			t.Created = ts
		case "resolved":
			ts, err := time.Parse(time.RFC3339Nano, val)
			if err != nil {
				ts, err = time.Parse(time.RFC3339, val)
				if err != nil {
					return t, fmt.Errorf("bad resolved time: %w", err)
				}
			}
			t.Resolved = ts
		case "due":
			ts, err := time.Parse(time.RFC3339Nano, val)
			if err != nil {
				ts, err = time.Parse(time.RFC3339, val)
				if err != nil {
					return t, fmt.Errorf("bad due time: %w", err)
				}
			}
			t.Due = ts
		}
		i++
	}

	return t, nil
}

func unquoteYAML(s string) string {
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		inner := s[1 : len(s)-1]
		inner = strings.ReplaceAll(inner, "\\\"", "\"")
		inner = strings.ReplaceAll(inner, "\\\\", "\\")
		return inner
	}
	return s
}
