package main

import (
	"fmt"
	"sort"
	"strings"
	"time"
	"unicode"
)

type Priority string

const (
	PriorityP0  Priority = "P0"
	PriorityP1  Priority = "P1"
	PriorityP2  Priority = "P2"
	PriorityP3  Priority = "P3"
	PriorityNone Priority = ""
)

var priorityOrder = map[Priority]int{
	PriorityP0: 0,
	PriorityP1: 1,
	PriorityP2: 2,
	PriorityP3: 3,
	PriorityNone: 2, // default = P2
}

type Status string

const (
	StatusPending  Status = "pending"
	StatusActive   Status = "active"
	StatusPaused   Status = "paused"
	StatusResolved Status = "resolved"
	StatusTemplate Status = "template"
)

// Task represents a dstask task
type Task struct {
	// Not stored in YAML, derived from:
	UUID   string `json:"uuid"`
	Status Status `json:"status"`
	ID     int    `json:"id"`

	// Stored in YAML
	Summary     string    `json:"summary"`
	Notes       string    `json:"notes"`
	Tags        []string  `json:"tags"`
	Project     string    `json:"project"`
	Priority    Priority  `json:"priority"`
	DelegatedTo string    `json:"-"`
	Subtasks    []string  `json:"-"`
	Dependencies []string `json:"-"`
	Created     time.Time `json:"created"`
	Resolved    time.Time `json:"resolved"`
	Due         time.Time `json:"due"`
}

// effectivePriority returns the priority order (lower = higher priority)
func (t *Task) effectivePriority() int {
	if t.Priority == PriorityNone {
		return 2
	}
	if v, ok := priorityOrder[t.Priority]; ok {
		return v
	}
	return 2
}

func (t *Task) priorityStr() string {
	if t.Priority == PriorityNone {
		return "P2"
	}
	return string(t.Priority)
}

// Query represents a filter/context
type Query struct {
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Priority      string
	Text          string
	IgnoreContext bool
}

// ParseArgs parses command line arguments into various components
// Returns: IDs, command, query, notes, noteArgs
func ParseArgs(args []string) (ids []int, cmd string, query Query, rawArgs []string) {
	// Find the command and IDs
	// IDs can appear before or after the command
	// Format: [id...] <cmd> [args]
	//         <cmd> [id...] [args]

	i := 0
	for i < len(args) {
		if id, ok := parseID(args[i]); ok {
			ids = append(ids, id)
			i++
		} else {
			// This is the command
			cmd = args[i]
			i++
			// Remaining are raw args
			rawArgs = args[i:]
			break
		}
	}

	// If no command found, try looking for command after IDs  
	// Actually the format says command is always first non-ID arg
	return
}

func parseID(s string) (int, bool) {
	if len(s) == 0 {
		return 0, false
	}
	n := 0
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, false
		}
		n = n*10 + int(c-'0')
	}
	return n, len(s) > 0
}

// ParseSummaryAndFilter parses task attributes from raw args
// Returns: summary words, tags, antiTags, project, antiProjects, priority, due, notes, ignoreContext
func ParseSummaryAndFilter(args []string) (summary string, tags []string, antiTags []string, project string, antiProjects []string, priority Priority, due time.Time, notes string, ignoreContext bool, templateID int) {
	var summaryWords []string
	var notesWords []string
	inNotes := false

	for _, arg := range args {
		if arg == "--" {
			ignoreContext = true
			continue
		}
		if arg == "/" {
			inNotes = true
			continue
		}
		if inNotes {
			notesWords = append(notesWords, arg)
			continue
		}

		// template:<id>
		if strings.HasPrefix(arg, "template:") {
			idStr := arg[len("template:"):]
			if id, ok := parseID(idStr); ok {
				templateID = id
			}
			continue
		}

		// +tag
		if strings.HasPrefix(arg, "+") {
			tagName := arg[1:]
			if tagName != "" {
				tags = append(tags, tagName)
			}
			continue
		}

		// -tag (but not --) 
		if strings.HasPrefix(arg, "-") && len(arg) > 1 && !strings.HasPrefix(arg, "--") {
			rest := arg[1:]
			// -project:name
			if strings.HasPrefix(rest, "project:") {
				projName := rest[len("project:"):]
				antiProjects = append(antiProjects, projName)
				continue
			}
			antiTags = append(antiTags, rest)
			continue
		}

		// project:name
		if strings.HasPrefix(arg, "project:") {
			projName := arg[len("project:"):]
			project = projName
			continue
		}

		// priority
		if arg == "P0" || arg == "P1" || arg == "P2" || arg == "P3" {
			priority = Priority(arg)
			continue
		}

		// due:YYYY-MM-DD
		if strings.HasPrefix(arg, "due:") {
			dateStr := arg[len("due:"):]
			t, err := time.Parse("2006-01-02", dateStr)
			if err == nil {
				due = t
			}
			continue
		}

		// regular word -> summary
		summaryWords = append(summaryWords, arg)
	}

	summary = strings.Join(summaryWords, " ")
	notes = strings.Join(notesWords, " ")
	return
}

// ParseContextArgs parses context filter args (simpler, no summary)
func ParseContextArgs(args []string) Query {
	var q Query
	for _, arg := range args {
		if arg == "--" {
			q.IgnoreContext = true
			continue
		}
		if strings.HasPrefix(arg, "+") {
			tagName := arg[1:]
			if tagName != "" {
				q.Tags = append(q.Tags, tagName)
			}
			continue
		}
		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			rest := arg[1:]
			if strings.HasPrefix(rest, "project:") {
				projName := rest[len("project:"):]
				q.AntiProjects = append(q.AntiProjects, projName)
				continue
			}
			q.AntiTags = append(q.AntiTags, rest)
			continue
		}
		if strings.HasPrefix(arg, "project:") {
			q.Project = arg[len("project:"):]
			continue
		}
		if arg == "P0" || arg == "P1" || arg == "P2" || arg == "P3" {
			q.Priority = arg
			continue
		}
		// text search
		if q.Text != "" {
			q.Text += " "
		}
		q.Text += arg
	}
	return q
}

// FormatContext formats a Query as a context string
func FormatContext(q Query) string {
	var parts []string
	for _, t := range q.Tags {
		parts = append(parts, "+"+t)
	}
	for _, t := range q.AntiTags {
		parts = append(parts, "-"+t)
	}
	if q.Project != "" {
		parts = append(parts, "project:"+q.Project)
	}
	for _, p := range q.AntiProjects {
		parts = append(parts, "-project:"+p)
	}
	if q.Priority != "" {
		parts = append(parts, q.Priority)
	}
	if q.Text != "" {
		parts = append(parts, q.Text)
	}
	return strings.Join(parts, " ")
}

// MatchesQuery returns true if task matches the given query
func (t *Task) MatchesQuery(q Query) bool {
	// Check tags (task must have ALL required tags)
	for _, tag := range q.Tags {
		if !containsString(t.Tags, tag) {
			return false
		}
	}

	// Check anti-tags (task must NOT have any anti-tags)
	for _, tag := range q.AntiTags {
		if containsString(t.Tags, tag) {
			return false
		}
	}

	// Check project
	if q.Project != "" && t.Project != q.Project {
		return false
	}

	// Check anti-projects
	for _, p := range q.AntiProjects {
		if t.Project == p {
			return false
		}
	}

	// Check priority
	if q.Priority != "" && string(t.Priority) != q.Priority {
		return false
	}

	// Check text (case-insensitive substring match)
	if q.Text != "" {
		lowerText := strings.ToLower(q.Text)
		if !strings.Contains(strings.ToLower(t.Summary), lowerText) &&
			!strings.Contains(strings.ToLower(t.Notes), lowerText) {
			return false
		}
	}

	return true
}

// SortTasks sorts tasks by priority then by creation date
func SortTasks(tasks []Task) {
	sort.Slice(tasks, func(i, j int) bool {
		pi := tasks[i].effectivePriority()
		pj := tasks[j].effectivePriority()
		if pi != pj {
			return pi < pj
		}
		return tasks[i].Created.Before(tasks[j].Created)
	})
}

func containsString(slice []string, s string) bool {
	for _, v := range slice {
		if v == s {
			return true
		}
	}
	return false
}

// NormalizeTags sorts and deduplicates tags
func NormalizeTags(tags []string) []string {
	seen := map[string]bool{}
	var result []string
	for _, t := range tags {
		if !seen[t] {
			seen[t] = true
			result = append(result, t)
		}
	}
	sort.Strings(result)
	return result
}

// TagsString formats tags as space-separated string
func TagsString(tags []string) string {
	return strings.Join(tags, " ")
}

// FormatDue formats a due date for display (returns "" if zero)
func FormatDue(due time.Time) string {
	if due.IsZero() || due.Year() == 1 {
		return ""
	}
	return due.Format("_2 Jan 2006")
}

// ExtractURLs finds all URLs in a string
func ExtractURLs(s string) []string {
	var urls []string
	words := strings.Fields(s)
	for _, w := range words {
		if strings.HasPrefix(w, "http://") || strings.HasPrefix(w, "https://") {
			urls = append(urls, w)
		}
	}
	return urls
}

// IsValidTag returns true if a string is a valid tag
func IsValidTag(s string) bool {
	for _, c := range s {
		if !unicode.IsLetter(c) && !unicode.IsDigit(c) && c != '-' && c != '_' {
			return false
		}
	}
	return len(s) > 0
}

// FormatTags for display
func FormatTagsDisplay(tags []string) string {
	return strings.Join(tags, " ")
}

func formatError(format string, args ...interface{}) {
	fmt.Printf("\033[31m"+format+"\033[0m\n", args...)
}

func formatWarning(format string, args ...interface{}) {
	fmt.Printf("\033[33m"+format+"\033[0m\n", args...)
}
