			q.Priority = arg
			continue
		}
		// text search
		if q.Text != "" {
			q.Text += " "
		}
		q.Text += arg
	}
	return q
}

// FormatContext formats a Query as a context string
func FormatContext(q Query) string {
	var parts []string
	for _, t := range q.Tags {
		parts = append(parts, "+"+t)
	}
	for _, t := range q.AntiTags {
		parts = append(parts, "-"+t)
	}
	if q.Project != "" {
		parts = append(parts, "project:"+q.Project)
	}
	for _, p := range q.AntiProjects {
		parts = append(parts, "-project:"+p)
	}
	if q.Priority != "" {
		parts = append(parts, q.Priority)
	}
	if q.Text != "" {
		parts = append(parts, q.Text)
	}
	return strings.Join(parts, " ")
}

// MatchesQuery returns true if task matches the given query
func (t *Task) MatchesQuery(q Query) bool {
	// Check tags (task must have ALL required tags)
	for _, tag := range q.Tags {
		if !containsString(t.Tags, tag) {
			return false
		}
	}

	// Check anti-tags (task must NOT have any anti-tags)
	for _, tag := range q.AntiTags {
		if containsString(t.Tags, tag) {
			return false
		}
	}

	// Check project
	if q.Project != "" && t.Project != q.Project {
		return false
	}

	// Check anti-projects
	for _, p := range q.AntiProjects {
		if t.Project == p {
			return false
		}
	}

	// Check priority
	if q.Priority != "" && string(t.Priority) != q.Priority {
		return false
	}

	// Check text (case-insensitive substring match)
	if q.Text != "" {
		lowerText := strings.ToLower(q.Text)
		if !strings.Contains(strings.ToLower(t.Summary), lowerText) &&
			!strings.Contains(strings.ToLower(t.Notes), lowerText) {
			return false
		}
	}

	return true
}

// SortTasks sorts tasks by priority then by creation date
func SortTasks(tasks []Task) {
	sort.Slice(tasks, func(i, j int) bool {
		pi := tasks[i].effectivePriority()
		pj := tasks[j].effectivePriority()
		if pi != pj {
			return pi < pj
		}
		return tasks[i].Created.Before(tasks[j].Created)
	})
}

func containsString(slice []string, s string) bool {
	for _, v := range slice {
		if v == s {
			return true
		}
	}
	return false
}

// NormalizeTags sorts and deduplicates tags
func NormalizeTags(tags []string) []string {
	seen := map[string]bool{}
	var result []string
	for _, t := range tags {
		if !seen[t] {
			seen[t] = true
			result = append(result, t)
		}
	}
	sort.Strings(result)
	return result
}

// TagsString formats tags as space-separated string
func TagsString(tags []string) string {
	return strings.Join(tags, " ")
}

// FormatDue formats a due date for display (returns "" if zero)
func FormatDue(due time.Time) string {
	if due.IsZero() || due.Year() == 1 {
		return ""
	}
	return due.Format("_2 Jan 2006")
}

// ExtractURLs finds all URLs in a string
func ExtractURLs(s string) []string {
	var urls []string
	words := strings.Fields(s)
	for _, w := range words {
		if strings.HasPrefix(w, "http://") || strings.HasPrefix(w, "https://") {
			urls = append(urls, w)
		}
	}
	return urls
}

// IsValidTag returns true if a string is a valid tag
func IsValidTag(s string) bool {
	for _, c := range s {
		if !unicode.IsLetter(c) && !unicode.IsDigit(c) && c != '-' && c != '_' {
			return false
		}
	}
	return len(s) > 0
}

// FormatTags for display
func FormatTagsDisplay(tags []string) string {
	return strings.Join(tags, " ")
}

func formatError(format string, args ...interface{}) {
	fmt.Printf("\033[31m"+format+"\033[0m\n", args...)
}

func formatWarning(format string, args ...interface{}) {
	fmt.Printf("\033[33m"+format+"\033[0m\n", args...)
}
