package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/google/uuid"
)

// StatusDirs maps status to directory
var StatusDirs = map[Status]string{
	StatusPending:  "pending",
	StatusActive:   "active",
	StatusPaused:   "paused",
	StatusResolved: "resolved",
	StatusTemplate: "template",
}

// AllStatusDirs all possible directories
var AllStatusDirs = []string{"pending", "active", "paused", "resolved", "template", "recurring", "deferred", "delegated"}

// OpenStatuses = non-resolved, non-template statuses
var OpenStatuses = []Status{StatusPending, StatusActive, StatusPaused}

// TaskSet manages the collection of tasks
type TaskSet struct {
	repoPath string
	IDs      IDsMap
}

func NewTaskSet(repoPath string) (*TaskSet, error) {
	ids, err := loadIDsMap(repoPath)
	if err != nil {
		return nil, err
	}

	// Also rebuild from filesystem (in case ids.json is missing/corrupt)
	if len(ids) == 0 {
		ids, err = rebuildIDsMap(repoPath)
		if err != nil {
			return nil, err
		}
	}

	return &TaskSet{
		repoPath: repoPath,
		IDs:      ids,
	}, nil
}

// rebuildIDsMap rebuilds IDs from the filesystem
func rebuildIDsMap(repoPath string) (IDsMap, error) {
	ids := IDsMap{}

	// Load all non-resolved tasks and assign IDs
	var tasks []Task
	for _, status := range []Status{StatusPending, StatusActive, StatusPaused, StatusTemplate} {
		dir := filepath.Join(repoPath, StatusDirs[status])
		tasksInDir, err := loadTasksFromDir(dir, status)
		if err != nil {
			return nil, err
		}
		tasks = append(tasks, tasksInDir...)
	}

	// Sort by created time to assign deterministic IDs
	sort.Slice(tasks, func(i, j int) bool {
		return tasks[i].Created.Before(tasks[j].Created)
	})

	for i, t := range tasks {
		ids[i+1] = t.UUID
	}

	return ids, nil
}

func loadTasksFromDir(dir string, status Status) ([]Task, error) {
	entries, err := os.ReadDir(dir)
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}

	var tasks []Task
	for _, e := range entries {
		if !strings.HasSuffix(e.Name(), ".yml") {
			continue
		}

		uuid := strings.TrimSuffix(e.Name(), ".yml")
		data, err := os.ReadFile(filepath.Join(dir, e.Name()))
		if err != nil {
			return nil, err
		}

		t, err := decodeYAML(string(data))
		if err != nil {
			return nil, fmt.Errorf("failed to parse %s: %w", e.Name(), err)
		}

		t.UUID = uuid
		t.Status = status
		tasks = append(tasks, t)
	}

	return tasks, nil
}

// GetTaskByID returns the task with the given ID
func (ts *TaskSet) GetTaskByID(id int) (*Task, error) {
	uuidStr, ok := ts.IDs[id]
	if !ok {
		return nil, fmt.Errorf("no open task with ID %d exists", id)
	}

	// Search in all non-resolved directories
	for _, status := range []Status{StatusPending, StatusActive, StatusPaused, StatusTemplate} {
		dir := filepath.Join(ts.repoPath, StatusDirs[status])
		path := filepath.Join(dir, uuidStr+".yml")
		data, err := os.ReadFile(path)
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return nil, err
		}

		t, err := decodeYAML(string(data))
		if err != nil {
			return nil, err
		}
		t.UUID = uuidStr
		t.Status = status
		t.ID = id
		return &t, nil
	}

	return nil, fmt.Errorf("no open task with ID %d exists", id)
}

// GetOpenTaskByID returns a task that is open (pending/active/paused)
func (ts *TaskSet) GetOpenTaskByID(id int) (*Task, error) {
	uuidStr, ok := ts.IDs[id]
	if !ok {
		return nil, fmt.Errorf("no open task with ID %d exists", id)
	}

