package main

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
)

func gitCmd(repoPath string, args ...string) (string, error) {
	cmd := exec.Command("git", append([]string{"-C", repoPath}, args...)...)
	out, err := cmd.CombinedOutput()
	return string(out), err
}

func gitAdd(repoPath string, paths ...string) error {
	args := append([]string{"add"}, paths...)
	_, err := gitCmd(repoPath, args...)
	return err
}

func gitCommit(repoPath string, message string) error {
	_, err := gitCmd(repoPath, "commit", "-m", message)
	return err
}

func gitAddAndCommit(repoPath string, message string) error {
	if err := gitAdd(repoPath, "-A"); err != nil {
		return err
	}
	out, err := gitCmd(repoPath, "commit", "-m", message)
	// Print commit output in dim color
	if out != "" {
		fmt.Printf("\033[38;5;245m%s\033[0m", out)
	}
	return err
}

func gitInit(repoPath string) error {
	_, err := gitCmd(repoPath, "init")
	return err
}

// initRepo initializes the repository if it doesn't exist
func initRepo(repoPath string) error {
	// Check if it's already a git repo
	_, err := os.Stat(repoPath + "/.git")
	if os.IsNotExist(err) {
		if err := os.MkdirAll(repoPath, 0755); err != nil {
			return err
		}
		if _, err := gitCmd(repoPath, "init"); err != nil {
			return err
		}
		fmt.Println()
		fmt.Printf("Add a remote repository with:\n\n\tdstask git remote add origin <repo>\n\n")
	} else if err != nil {
		return err
	}

	return EnsureDirs(repoPath)
}

func gitSync(repoPath string) error {
	// Pull
	pullOut, pullErr := gitCmd(repoPath, "pull", "--no-rebase")
	if pullOut != "" {
		fmt.Print(pullOut)
	}
	if pullErr != nil {
		// Try to merge
		mergeOut, mergeErr := gitCmd(repoPath, "merge", "--strategy-option=theirs")
		if mergeOut != "" {
			fmt.Print(mergeOut)
		}
		if mergeErr != nil {
			return fmt.Errorf("pull failed: %v", pullErr)
		}
	}

	// Push
	pushOut, pushErr := gitCmd(repoPath, "push")
	if pushOut != "" {
		fmt.Print(pushOut)
	}
	return pushErr
}

func gitUndo(repoPath string, n int) error {
	out, err := gitCmd(repoPath, "revert", "--no-edit", fmt.Sprintf("HEAD~%d..HEAD", n))
	if out != "" {
		fmt.Print(out)
	}
	return err
}

func gitPassthrough(repoPath string, args []string) error {
	cmd := exec.Command("git", append([]string{"-C", repoPath}, args...)...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Stdin = os.Stdin
	return cmd.Run()
}

// checkGitConfig checks if git user.email and user.name are set
func checkGitConfig() (bool, bool) {
	emailOut, _ := exec.Command("git", "config", "user.email").Output()
	nameOut, _ := exec.Command("git", "config", "user.name").Output()
	return strings.TrimSpace(string(emailOut)) != "", strings.TrimSpace(string(nameOut)) != ""
}
