	case PriorityP1:
		if i%2 == 0 {
			return colorP1Even
		}
		return colorP1Odd
	case PriorityP3:
		return colorP3
	default: // P2 or none
		if i%2 == 0 {
			return colorP2Even
		}
		return colorP2Odd
	}
}

func getRowFgColor(t Task, i int) string {
	switch t.Status {
	case StatusActive:
		return "\033[38;5;130m"
	case StatusPaused:
		return "\033[38;5;166m"
	}
	switch t.Priority {
