// TableOutput outputs tasks as a colored table
func TableOutput(tasks []Task, showContext bool, contextStr string, fromEnv bool, truncate int) {
	if showContext && contextStr != "" {
		if fromEnv {
			fmt.Printf("%sActive context (set by DSTASK_CONTEXT): %s%s\n", colorWarning, contextStr, colorReset)
		} else {
			fmt.Printf("%sActive context: %s%s\n", colorWarning, contextStr, colorReset)
		}
	}

	if len(tasks) == 0 {
		fmt.Fprintf(os.Stderr, "%sNo matching tasks in given context or filter.%s\n", colorError, colorReset)
		os.Exit(1)
	}

	termWidth := getTermWidth()

	// Determine column widths
	idWidth := 2     // "ID"
	priWidth := 8    // "Priority"
	tagsWidth := 4   // "Tags"
	dueWidth := 3    // "Due"
	projectWidth := 7 // "Project"

	for _, t := range tasks {
		idStr := fmt.Sprintf("%d", t.ID)
		if len(idStr) > idWidth {
			idWidth = len(idStr)
		}

		tagsStr := TagsString(t.Tags)
		if len(tagsStr) > tagsWidth {
			tagsWidth = len(tagsStr)
		}

		dueStr := FormatDue(t.Due)
		if len(dueStr) > dueWidth {
			dueWidth = len(dueStr)
		}

		if len(t.Project) > projectWidth {
			projectWidth = len(t.Project)
		}
	}

	// Add padding
	idWidth += 2
	priWidth += 2
	tagsWidth += 2
	dueWidth += 2
	projectWidth += 2

	// Fixed columns total
	fixedWidth := idWidth + priWidth + tagsWidth + dueWidth

	// Remaining for project + summary
	remaining := termWidth - fixedWidth
	if remaining < 10 {
		remaining = 10
	}

	// Project gets at most ceil(remaining/2)
	projectMax := (remaining + 1) / 2
	if projectWidth > projectMax {
		projectWidth = projectMax
	}

	// Summary gets the rest
	summaryWidth := remaining - projectWidth
	if summaryWidth < 7 {
		summaryWidth = 7
	}

	// Print header
	header := padRight("ID", idWidth) +
		padRight("Priority", priWidth) +
		padRight("Tags", tagsWidth) +
		padRight("Due", dueWidth) +
		padRight("Project", projectWidth) +
		"Summary"
	// Pad header to total width
	headerTotal := idWidth + priWidth + tagsWidth + dueWidth + projectWidth + summaryWidth
	header = padRight("ID", idWidth) +
		padRight("Priority", priWidth) +
		padRight("Tags", tagsWidth) +
		padRight("Due", dueWidth) +
		padRight("Project", projectWidth) +
		padRight("Summary", summaryWidth)
	_ = headerTotal
	fmt.Printf("%s%s%s\n", colorHeader, header, colorReset)

	total := len(tasks)
	shown := 0

	for i, t := range tasks {
		if truncate > 0 && shown >= truncate {
			break
		}
		shown++

		// Determine row color
		rowColor := getRowColor(t, i)

		idStr := padRight(fmt.Sprintf("%d", t.ID), idWidth)
		priStr := padRight(t.priorityStr(), priWidth)
		tagsStr := padRight(truncStr(TagsString(t.Tags), tagsWidth-2), tagsWidth)
		dueStr := padRight(truncStr(FormatDue(t.Due), dueWidth-2), dueWidth)
		projStr := padRight(truncStr(t.Project, projectWidth-2), projectWidth)

		// Summary: show summary + notes in different color
		sumContent := t.Summary
		notesContent := ""
		if t.Notes != "" {
			// Show notes inline in dim color
			firstLine := strings.Split(t.Notes, "\n")[0]
			notesContent = " " + firstLine
		}

		// Truncate summary + notes to fit summaryWidth
		sumMaxLen := summaryWidth - 1
		totalSumLen := utf8.RuneCountInString(sumContent) + utf8.RuneCountInString(notesContent)
		_ = totalSumLen

		var sumLine string
		if notesContent == "" {
			sumLine = padRight(truncStr(sumContent, summaryWidth-1), summaryWidth)
			fmt.Printf("%s%s%s%s%s%s%s\n",
				rowColor, idStr, priStr, tagsStr, dueStr, projStr, sumLine+colorReset)
		} else {
			// Need to show summary then notes in different color
			sumLen := utf8.RuneCountInString(sumContent)
			notesLen := utf8.RuneCountInString(notesContent)

			if sumLen+notesLen > sumMaxLen {
				if sumLen >= sumMaxLen {
					// Truncate summary only
					sumLine = padRight(truncStr(sumContent, sumMaxLen), summaryWidth)
					fmt.Printf("%s%s%s%s%s%s%s%s\n",
						rowColor, idStr, priStr, tagsStr, dueStr, projStr, sumLine, colorReset)
				} else {
					// Show summary, then notes truncated
					remaining2 := sumMaxLen - sumLen
					notesTrunc := truncStr(notesContent, remaining2)
					padding := summaryWidth - sumLen - utf8.RuneCountInString(notesTrunc)
					if padding < 0 {
						padding = 0
					}
					// Get the fg color for the row to restore after notes
					fgColor := getRowFgColor(t, i)
					fmt.Printf("%s%s%s%s%s%s%s%s%s%s%s\n",
						rowColor, idStr, priStr, tagsStr, dueStr, projStr,
						sumContent,
						colorNotesText, notesTrunc,
						fgColor, strings.Repeat(" ", padding)+colorReset)
				}
			} else {
				// Both fit
				padding := summaryWidth - sumLen - utf8.RuneCountInString(notesContent)
				if padding < 0 {
					padding = 0
				}
				fgColor := getRowFgColor(t, i)
				fmt.Printf("%s%s%s%s%s%s%s%s%s%s%s\n",
					rowColor, idStr, priStr, tagsStr, dueStr, projStr,
					sumContent,
					colorNotesText, notesContent,
					fgColor, strings.Repeat(" ", padding)+colorReset)
			}
		}
	}

	fmt.Println()
	if truncate > 0 && shown < total {
		fmt.Printf("%d/%d tasks shown.\n", shown, total)
	} else {
		fmt.Printf("%d tasks.\n", shown)
	}
}

func getRowColor(t Task, i int) string {
	switch t.Status {
	case StatusActive:
		return colorActive
	case StatusPaused:
		return colorPaused
	}

	// By priority, alternating rows
	switch t.Priority {
	case PriorityP0:
		return colorP0
	case PriorityP1:
		if i%2 == 0 {
			return colorP1Even
		}
		return colorP1Odd
	case PriorityP3:
		return colorP3
	default: // P2 or none
		if i%2 == 0 {
			return colorP2Even
		}
		return colorP2Odd
	}
}

func getRowFgColor(t Task, i int) string {
	switch t.Status {
	case StatusActive:
		return "\033[38;5;130m"
	case StatusPaused:
		return "\033[38;5;166m"
	}
	switch t.Priority {
	case PriorityP0:
		return "\033[38;5;160m"
	case PriorityP1:
		return "\033[38;5;166m"
	case PriorityP3:
		return "\033[38;5;245m"
	default:
		return "\033[38;5;250m"
	}
}

func padRight(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s[:width]
	}
	return s + strings.Repeat(" ", width-l)
}

func truncStr(s string, maxLen int) string {
	runes := []rune(s)
	if len(runes) <= maxLen {
		return s
	}
	return string(runes[:maxLen])
}

// SingleTaskDetails shows a detailed view of a single task
func SingleTaskDetails(t Task) {
	termWidth := getTermWidth()
	nameWidth := 10
	valueWidth := termWidth - nameWidth - 2

	rows := [][]string{
		{"ID", fmt.Sprintf("%d", t.ID)},
		{"Priority", t.priorityStr()},
		{"Summary", t.Summary},
		{"Status", string(t.Status)},
		{"Project", t.Project},
		{"Tags", TagsString(t.Tags)},
		{"UUID", t.UUID},
		{"Created", t.Created.String()},
	}

	if !t.Due.IsZero() && t.Due.Year() > 1 {
		rows = append(rows, []string{"Due", t.Due.String()})
	}

	if t.Notes != "" {
		rows = append(rows, []string{"Notes", t.Notes})
	}

	// Print header
	header := padRight("Name", nameWidth+2) + "Value"
	_ = valueWidth
	fmt.Printf("%s%s%s\n", colorHeader, padRight(header, termWidth), colorReset)

	for i, row := range rows {
		var rowColor string
		if i%2 == 0 {
			rowColor = colorP2Odd
		} else {
			rowColor = colorP2Even
		}
		name := padRight(row[0], nameWidth+2)
		value := padRight(row[1], termWidth-nameWidth-2)
		fmt.Printf("%s%s%s%s\n", rowColor, name, value, colorReset)
	}
}

