package main

import (
	"os"
	"syscall"
	"unsafe"
)

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getTerminalWidth() int {
	if os.Getenv("DSTASK_FAKE_PTY") != "" {
		return 80
	}
	ws := &winsize{}
	ret, _, _ := syscall.Syscall(
		syscall.SYS_IOCTL,
		uintptr(syscall.Stdout),
		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(ws)),
	)
	if int(ret) == -1 {
		return 80
	}
	if ws.Col == 0 {
		return 80
	}
	return int(ws.Col)
}

func isTerminalOutput() bool {
	if os.Getenv("DSTASK_FAKE_PTY") != "" {
		return true
	}
	// Check if stdout is a terminal
	_, _, errno := syscall.Syscall(
		syscall.SYS_IOCTL,
		uintptr(syscall.Stdout),
		uintptr(syscall.TIOCGWINSZ),
		uintptr(0),
	)
	// If no error, it's a terminal (the ioctl succeeded)
	// Actually we should just check with isatty
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	_ = errno
	return (fi.Mode() & os.ModeCharDevice) != 0
}
