				} else {
					rem2 := sumMaxLen - sumLen
					notesTrunc := truncStr(notesContent, rem2)
					padding := summaryWidth - sumLen - utf8.RuneCountInString(notesTrunc)
					if padding < 0 {
						padding = 0
					}
					fgColor := getRowFgColor(t, i)
					fmt.Printf("%s%s%s%s%s%s%s%s%s%s%s%s\n",
