// CommandAdd handles the "add" command
func CommandAdd(ts *TaskSet, repoPath string, args []string, ctx Query, fromEnv bool) error {
	// Parse args
	summary, tags, antiTags, project, _, priority, due, notes, ignoreContext, templateID := ParseSummaryAndFilter(args)
	_ = antiTags

	if summary == "" && templateID == 0 {
		return fmt.Errorf("task summary required")
	}

	// Apply context
	if !ignoreContext {
		tags = mergeContextTags(tags, ctx)
		if project == "" && ctx.Project != "" {
			project = ctx.Project
		}
	}

	var t *Task
	var err error

	if templateID > 0 {
		// Create from template
		tmpl, err := ts.GetTaskByID(templateID)
		if err != nil {
			return err
		}
		if tmpl.Status != StatusTemplate {
			return fmt.Errorf("task %d is not a template", templateID)
		}

		// Start with template properties
		tmplTags := tmpl.Tags
		tmplProject := tmpl.Project
		tmplPriority := tmpl.Priority
		tmplNotes := tmpl.Notes

		// Override with provided values
		if len(tags) > 0 {
			// Merge tags
			merged := append(tmplTags, tags...)
			tmplTags = NormalizeTags(merged)
		}
		if project != "" {
			tmplProject = project
		}
		if priority != PriorityNone {
			tmplPriority = priority
		}

		finalSummary := tmpl.Summary
		if summary != "" {
			finalSummary = summary
		}

		t, err = ts.CreateTask(finalSummary, tmplNotes+notes, tmplTags, tmplProject, tmplPriority, due)
	} else {
		t, err = ts.CreateTask(summary, notes, tags, project, priority, due)
	}

	if err != nil {
		return err
	}

	fmt.Printf("\nAdded %d: %s\n", t.ID, t.Summary)

	return gitAddAndCommit(repoPath, fmt.Sprintf("Added %d: %s", t.ID, t.Summary))
}

func mergeContextTags(tags []string, ctx Query) []string {
	merged := append([]string{}, tags...)
	for _, ctxTag := range ctx.Tags {
		if !containsString(merged, ctxTag) {
			merged = append(merged, ctxTag)
		}
	}
	// Remove anti-tags from context
	var filtered []string
	for _, t := range merged {
		if !containsString(ctx.AntiTags, t) {
			filtered = append(filtered, t)
		}
	}
	return filtered
}

// CommandTemplate handles the "template" command
func CommandTemplate(ts *TaskSet, repoPath string, args []string, ctx Query) error {
	// Check if first arg is an ID
	if len(args) > 0 {
		if id, ok := parseID(args[0]); ok {
			// Convert existing task to template
			t, err := ts.GetOpenTaskByID(id)
			if err != nil {
				return err
			}
			oldStatus := t.Status
			_ = oldStatus

			oldPath := fmt.Sprintf("%s/%s/%s.yml", repoPath, StatusDirs[t.Status], t.UUID)
			t.Status = StatusTemplate
			newPath := fmt.Sprintf("%s/%s/%s.yml", repoPath, StatusDirs[StatusTemplate], t.UUID)

			if err := os.Rename(oldPath, newPath); err != nil {
				return err
			}

			fmt.Printf("\nChanged %d: %s to Template\n", id, t.Summary)
			return gitAddAndCommit(repoPath, fmt.Sprintf("Changed %d: %s to Template", id, t.Summary))
		}
	}

	// Create new template
	summary, tags, _, project, _, priority, due, notes, ignoreContext, _ := ParseSummaryAndFilter(args)

	// Apply context
	if !ignoreContext {
		tags = mergeContextTags(tags, ctx)
		if project == "" && ctx.Project != "" {
			project = ctx.Project
		}
	}

	t, err := ts.CreateTemplate(summary, notes, tags, project, priority, due)
	if err != nil {
		return err
	}

	fmt.Printf("\nCreated Template %d: %s\n", t.ID, t.Summary)
	return gitAddAndCommit(repoPath, fmt.Sprintf("Created Template %d: %s", t.ID, t.Summary))
}

