// CommandModify handles "modify"
func CommandModify(ts *TaskSet, repoPath string, ids []int, args []string, ctx Query) error {
	// Parse modification args (tags, antiTags, project, priority)
	_, tags, antiTags, project, antiProjects, priority, due, _, _, _ := ParseSummaryAndFilter(args)

	hasOp := len(tags) > 0 || len(antiTags) > 0 || project != "" || len(antiProjects) > 0 || priority != PriorityNone || !due.IsZero()
	if !hasOp {
		// Check if user wants to clear project with -project:
		hasClear := false
		for _, arg := range args {
			if strings.HasPrefix(arg, "-project:") {
				hasClear = true
				break
			}
		}
		if !hasClear {
			fmt.Fprintf(os.Stderr, "%sno operations specified%s\n", colorError, colorReset)
			return nil
		}
	}

	// If no IDs given, modify all tasks in context (with confirmation)
	if len(ids) == 0 {
		tasks, err := ts.GetAllTasks([]Status{StatusPending, StatusActive, StatusPaused})
		if err != nil {
			return err
		}
		// Filter by context
		var filtered []Task
		for _, t := range tasks {
			if t.MatchesQuery(ctx) {
				filtered = append(filtered, t)
			}
		}
		if len(filtered) == 0 {
			fmt.Println("No tasks to modify")
			return nil
		}
		// Show tasks
		SortTasks(filtered)
		JSONOutput(filtered)
		fmt.Printf("\nModify all %d tasks? [y/N] ", len(filtered))
		scanner := bufio.NewScanner(os.Stdin)
		scanner.Scan()
		if strings.ToLower(strings.TrimSpace(scanner.Text())) != "y" {
			fmt.Println("Aborted")
			return nil
		}
		for _, t := range filtered {
			ids = append(ids, t.ID)
		}
	}

	for _, id := range ids {
		t, err := ts.GetOpenTaskByID(id)
		if err != nil {
			return err
		}

		// Apply modifications
		for _, tag := range tags {
			if !containsString(t.Tags, tag) {
				t.Tags = append(t.Tags, tag)
			}
		}
		for _, tag := range antiTags {
			t.Tags = removeString(t.Tags, tag)
		}
		t.Tags = NormalizeTags(t.Tags)

		if project != "" {
			t.Project = project
		}
		for _, ap := range antiProjects {
			if t.Project == ap {
				t.Project = ""
			}
		}
		// Also handle -project: with empty name (clear project)
		for _, arg := range args {
			if arg == "-project:" || arg == "-project" {
				t.Project = ""
			}
		}

		if priority != PriorityNone {
			t.Priority = priority
		}
		if !due.IsZero() {
			t.Due = due
		}

		if err := ts.UpdateTask(t); err != nil {
			return err
		}

		fmt.Printf("\nModified %d: %s\n", id, t.Summary)
		if err := gitAddAndCommit(repoPath, fmt.Sprintf("Modified %d: %s", id, t.Summary)); err != nil {
			return err
		}
	}
	return nil
}

// CommandNote handles "note" command
func CommandNote(ts *TaskSet, repoPath string, id int, args []string) error {
	t, err := ts.GetTaskByID(id)
	if err != nil {
		return err
	}

	if len(args) > 0 {
		// Append text to notes
		text := strings.Join(args, " ")
		if t.Notes != "" {
			t.Notes += "\n" + text
		} else {
			t.Notes = "\n" + text
		}

		if err := ts.UpdateTask(t); err != nil {
			return err
		}

		fmt.Printf("\nUpdated note for %d: %s\n", id, t.Summary)
		return gitAddAndCommit(repoPath, fmt.Sprintf("Note %d: %s", id, t.Summary))
	}

	// Open editor
	editor := os.Getenv("VISUAL")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = "vi"
	}

	// Create temp file
	tmpFile, err := os.CreateTemp("", "dstask-note-*.md")
	if err != nil {
		return err
	}
	tmpPath := tmpFile.Name()
	defer os.Remove(tmpPath)

	if _, err := tmpFile.WriteString(t.Notes); err != nil {
		tmpFile.Close()
		return err
	}
	tmpFile.Close()

	// Open editor
	cmd := exec.Command(editor, tmpPath)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return err
	}

	// Read back
	data, err := os.ReadFile(tmpPath)
	if err != nil {
		return err
	}

	t.Notes = strings.TrimRight(string(data), "\n")

	if err := ts.UpdateTask(t); err != nil {
		return err
	}

	return gitAddAndCommit(repoPath, fmt.Sprintf("Note %d: %s", id, t.Summary))
}

// CommandEdit handles "edit" command
func CommandEdit(ts *TaskSet, repoPath string, id int) error {
	t, err := ts.GetTaskByID(id)
	if err != nil {
		return err
	}

	editor := os.Getenv("VISUAL")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = "vi"
	}

	// Write to temp file
	tmpFile, err := os.CreateTemp("", "dstask-edit-*.yml")
	if err != nil {
		return err
	}
	tmpPath := tmpFile.Name()
	defer os.Remove(tmpPath)

	if _, err := tmpFile.WriteString(encodeYAML(*t)); err != nil {
		tmpFile.Close()
		return err
	}
	tmpFile.Close()

	cmd := exec.Command(editor, tmpPath)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return err
	}

	data, err := os.ReadFile(tmpPath)
	if err != nil {
		return err
	}

	updated, err := decodeYAML(string(data))
