	t, err := ts.GetTaskByID(id)
	if err != nil {
		return err
	}

	urls := ExtractURLs(t.Summary)
	urls = append(urls, ExtractURLs(t.Notes)...)

	if len(urls) == 0 {
		return fmt.Errorf("no URLs found in task %d", id)
	}

	for _, url := range urls {
		opener := "xdg-open"
		if _, err := exec.LookPath("open"); err == nil {
			opener = "open"
		}
		cmd := exec.Command(opener, url)
		cmd.Start()
	}

	return nil
}

