// CommandModify handles "modify"
func CommandModify(ts *TaskSet, repoPath string, ids []int, args []string, ctx Query) error {
	// Parse modification args (tags, antiTags, project, priority)
	_, tags, antiTags, project, antiProjects, priority, due, _, _, _ := ParseSummaryAndFilter(args)

	hasOp := len(tags) > 0 || len(antiTags) > 0 || project != "" || len(antiProjects) > 0 || priority != PriorityNone || !due.IsZero()
	if !hasOp {
		// Check if user wants to clear project with -project:
		hasClear := false
		for _, arg := range args {
			if strings.HasPrefix(arg, "-project:") {
				hasClear = true
				break
			}
		}
		if !hasClear {
			fmt.Fprintf(os.Stderr, "%sno operations specified%s\n", colorError, colorReset)
			return nil
		}
	}

	// If no IDs given, modify all tasks in context (with confirmation)
	if len(ids) == 0 {
		tasks, err := ts.GetAllTasks([]Status{StatusPending, StatusActive, StatusPaused})
		if err != nil {
			return err
		}
		// Filter by context
		var filtered []Task
		for _, t := range tasks {
			if t.MatchesQuery(ctx) {
				filtered = append(filtered, t)
			}
		}
		if len(filtered) == 0 {
			fmt.Println("No tasks to modify")
			return nil
		}
		// Show tasks
		SortTasks(filtered)
		JSONOutput(filtered)
		fmt.Printf("\nModify all %d tasks? [y/N] ", len(filtered))
		scanner := bufio.NewScanner(os.Stdin)
		scanner.Scan()
		if strings.ToLower(strings.TrimSpace(scanner.Text())) != "y" {
			fmt.Println("Aborted")
			return nil
		}
		for _, t := range filtered {
			ids = append(ids, t.ID)
		}
	}

	for _, id := range ids {
		t, err := ts.GetOpenTaskByID(id)
		if err != nil {
			return err
		}

		// Apply modifications
		for _, tag := range tags {
			if !containsString(t.Tags, tag) {
				t.Tags = append(t.Tags, tag)
			}
		}
		for _, tag := range antiTags {
			t.Tags = removeString(t.Tags, tag)
		}
		t.Tags = NormalizeTags(t.Tags)

		if project != "" {
			t.Project = project
		}
		for _, ap := range antiProjects {
			if t.Project == ap {
				t.Project = ""
			}
		}
		// Also handle -project: with empty name (clear project)
		for _, arg := range args {
			if arg == "-project:" || arg == "-project" {
				t.Project = ""
			}
		}

		if priority != PriorityNone {
			t.Priority = priority
		}
		if !due.IsZero() {
			t.Due = due
		}

		if err := ts.UpdateTask(t); err != nil {
			return err
		}

		fmt.Printf("\nModified %d: %s\n", id, t.Summary)
		if err := gitAddAndCommit(repoPath, fmt.Sprintf("Modified %d: %s", id, t.Summary)); err != nil {
			return err
		}
	}
	return nil
