func CommandNote(ts *TaskSet, repoPath string, id int, args []string) error {
	t, err := ts.GetTaskByID(id)
	if err != nil {
		return err
	}

	if len(args) > 0 {
		// Append text to notes
		text := strings.Join(args, " ")
		if t.Notes != "" {
			t.Notes += "\n" + text
		} else {
			t.Notes = "\n" + text
		}

		if err := ts.UpdateTask(t); err != nil {
			return err
		}

		fmt.Printf("\nUpdated note for %d: %s\n", id, t.Summary)
		return gitAddAndCommit(repoPath, fmt.Sprintf("Note %d: %s", id, t.Summary))
	}

	// Open editor
	editor := os.Getenv("VISUAL")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = "vi"
	}

	// Create temp file
	tmpFile, err := os.CreateTemp("", "dstask-note-*.md")
	if err != nil {
		return err
	}
	tmpPath := tmpFile.Name()
	defer os.Remove(tmpPath)

	if _, err := tmpFile.WriteString(t.Notes); err != nil {
		tmpFile.Close()
		return err
	}
	tmpFile.Close()

	// Open editor
	cmd := exec.Command(editor, tmpPath)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return err
	}

	// Read back
	data, err := os.ReadFile(tmpPath)
	if err != nil {
		return err
	}

	t.Notes = strings.TrimRight(string(data), "\n")

	if err := ts.UpdateTask(t); err != nil {
		return err
	}

	return gitAddAndCommit(repoPath, fmt.Sprintf("Note %d: %s", id, t.Summary))
