func CommandEdit(ts *TaskSet, repoPath string, id int) error {
	t, err := ts.GetTaskByID(id)
	if err != nil {
		return err
	}

	editor := os.Getenv("VISUAL")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = "vi"
	}

	// Write to temp file
	tmpFile, err := os.CreateTemp("", "dstask-edit-*.yml")
	if err != nil {
		return err
	}
	tmpPath := tmpFile.Name()
	defer os.Remove(tmpPath)

	if _, err := tmpFile.WriteString(encodeYAML(*t)); err != nil {
		tmpFile.Close()
		return err
	}
	tmpFile.Close()

	cmd := exec.Command(editor, tmpPath)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return err
	}

	data, err := os.ReadFile(tmpPath)
	if err != nil {
		return err
	}

	updated, err := decodeYAML(string(data))
	if err != nil {
		return err
	}

	// Preserve metadata
	updated.UUID = t.UUID
	updated.Status = t.Status
	updated.ID = t.ID
	updated.Created = t.Created

	if err := ts.UpdateTask(&updated); err != nil {
		return err
	}

	return gitAddAndCommit(repoPath, fmt.Sprintf("Edited %d: %s", id, updated.Summary))
}

// CommandOpen handles "open" command
func CommandOpen(ts *TaskSet, id int) error {
	t, err := ts.GetTaskByID(id)
	if err != nil {
		return err
	}

	urls := ExtractURLs(t.Summary)
	urls = append(urls, ExtractURLs(t.Notes)...)

	if len(urls) == 0 {
		return fmt.Errorf("no URLs found in task %d", id)
	}

	for _, url := range urls {
		opener := "xdg-open"
		if _, err := exec.LookPath("open"); err == nil {
			opener = "open"
		}
		cmd := exec.Command(opener, url)
		cmd.Start()
	}

	return nil
}

