			t.Project = project
		}
		for _, ap := range antiProjects {
			if t.Project == ap {
				t.Project = ""
			}
		}
		// Also handle -project: with empty name (clear project)
		for _, arg := range args {
			if arg == "-project:" || arg == "-project" {
				t.Project = ""
			}
		}

		if priority != PriorityNone {
			t.Priority = priority
		}
		if !due.IsZero() {
			t.Due = due
		}

		if err := ts.UpdateTask(t); err != nil {
			return err
		}

		fmt.Printf("\nModified %d: %s\n", id, t.Summary)
		if err := gitAddAndCommit(repoPath, fmt.Sprintf("Modified %d: %s", id, t.Summary)); err != nil {
			return err
		}
	}
	return nil
}

// CommandNote handles "note" command
func CommandNote(ts *TaskSet, repoPath string, id int, args []string) error {
	t, err := ts.GetTaskByID(id)
	if err != nil {
		return err
	}

	if len(args) > 0 {
		// Append text to notes
		text := strings.Join(args, " ")
		if t.Notes != "" {
			t.Notes += "\n" + text
		} else {
			t.Notes = "\n" + text
		}

		if err := ts.UpdateTask(t); err != nil {
			return err
		}

		fmt.Printf("\nUpdated note for %d: %s\n", id, t.Summary)
		return gitAddAndCommit(repoPath, fmt.Sprintf("Note %d: %s", id, t.Summary))
	}

	// Open editor
	editor := os.Getenv("VISUAL")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = "vi"
	}

	// Create temp file
	tmpFile, err := os.CreateTemp("", "dstask-note-*.md")
	if err != nil {
		return err
	}
	tmpPath := tmpFile.Name()
	defer os.Remove(tmpPath)

	if _, err := tmpFile.WriteString(t.Notes); err != nil {
		tmpFile.Close()
		return err
	}
	tmpFile.Close()

	// Open editor
	cmd := exec.Command(editor, tmpPath)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return err
	}

	// Read back
	data, err := os.ReadFile(tmpPath)
	if err != nil {
		return err
	}

	t.Notes = strings.TrimRight(string(data), "\n")

	if err := ts.UpdateTask(t); err != nil {
		return err
	}

	return gitAddAndCommit(repoPath, fmt.Sprintf("Note %d: %s", id, t.Summary))
}

// CommandEdit handles "edit" command
func CommandEdit(ts *TaskSet, repoPath string, id int) error {
	t, err := ts.GetTaskByID(id)
	if err != nil {
		return err
	}

	editor := os.Getenv("VISUAL")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = "vi"
	}

	// Write to temp file
	tmpFile, err := os.CreateTemp("", "dstask-edit-*.yml")
	if err != nil {
		return err
	}
	tmpPath := tmpFile.Name()
	defer os.Remove(tmpPath)

	if _, err := tmpFile.WriteString(encodeYAML(*t)); err != nil {
		tmpFile.Close()
		return err
	}
	tmpFile.Close()

	cmd := exec.Command(editor, tmpPath)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return err
	}

	data, err := os.ReadFile(tmpPath)
	if err != nil {
		return err
	}

	updated, err := decodeYAML(string(data))
	if err != nil {
		return err
	}

	// Preserve metadata
	updated.UUID = t.UUID
	updated.Status = t.Status
	updated.ID = t.ID
	updated.Created = t.Created

	if err := ts.UpdateTask(&updated); err != nil {
		return err
	}

	return gitAddAndCommit(repoPath, fmt.Sprintf("Edited %d: %s", id, updated.Summary))
}

// CommandOpen handles "open" command
func CommandOpen(ts *TaskSet, id int) error {
	t, err := ts.GetTaskByID(id)
	if err != nil {
		return err
	}

	urls := ExtractURLs(t.Summary)
	urls = append(urls, ExtractURLs(t.Notes)...)

	if len(urls) == 0 {
		return fmt.Errorf("no URLs found in task %d", id)
	}

	for _, url := range urls {
		opener := "xdg-open"
		if _, err := exec.LookPath("open"); err == nil {
			opener = "open"
		}
		cmd := exec.Command(opener, url)
		cmd.Start()
	}

	return nil
}

// CommandContext handles "context" command
func CommandContext(repoPath string, args []string) error {
	if len(args) == 0 || (len(args) == 1 && args[0] == "none") {
		// Clear context
		return SetContext(repoPath, Query{})
	}

	// Validate no text
	if err := validateContextFilter(args); err != nil {
		fmt.Fprintf(os.Stderr, "%s%s%s\n", colorError, err.Error(), colorReset)
		return nil
	}

	q := ParseContextArgs(args)
	return SetContext(repoPath, q)
}

