// CommandShowProjects handles "show-projects"
func CommandShowProjects(ts *TaskSet, ctx Query, ignoreCtx bool) error {
	// Get all tasks
	allTasks, err := ts.GetAllTasks([]Status{StatusPending, StatusActive, StatusPaused, StatusResolved, StatusTemplate})
	if err != nil {
		return err
	}

	// Build project info
	projects := map[string]*ProjectInfo{}

	for _, t := range allTasks {
		if t.Project == "" {
			continue
		}
		if t.Status == StatusTemplate {
			continue
		}

		p, ok := projects[t.Project]
		if !ok {
			p = &ProjectInfo{
				Name:     t.Project,
				Created:  t.Created,
				Resolved: t.Resolved,
				Priority: PriorityP3,
			}
			projects[t.Project] = p
		}

		p.TaskCount++
		if t.Status == StatusResolved {
			p.ResolvedCount++
			if t.Resolved.After(p.Resolved) {
				p.Resolved = t.Resolved
			}
		} else {
			p.Active = true
		}
		if t.Created.Before(p.Created) {
			p.Created = t.Created
		}

		// Track highest priority
		if priorityOrder[t.Priority] < priorityOrder[p.Priority] {
			p.Priority = t.Priority
		}
	}

	// Convert to slice and sort
	var projectList []ProjectInfo
	for _, p := range projects {
		projectList = append(projectList, *p)
	}

	sort.Slice(projectList, func(i, j int) bool {
		pi := priorityOrder[projectList[i].Priority]
		pj := priorityOrder[projectList[j].Priority]
		if pi != pj {
			return pi < pj
		}
		return projectList[i].Name < projectList[j].Name
	})

	if isTerminalOutput() {
		ProjectsTableOutput(projectList)
	} else {
		JSONProjectsOutput(projectList)
	}
	return nil
}

