			os.Exit(1)
		}
		if err := CommandDone(ts, repoPath, ids, remaining, ctx, false); err != nil {
			fmt.Fprintf(os.Stderr, "%s%v%s\n", colorError, err, colorReset)
			os.Exit(1)
		}
		return

